<template>
  <section class="signature-project" :class="{ 'signature-project-reverse': entry.id === 'searchstory' }" :style="{ '--views-overflow': `${viewsOverflow}px` }" :aria-labelledby="`${entry.id}-feature-title`">
    <div class="signature-project-copy">
      <span class="signature-project-kicker">{{ showcase.category }}</span>
      <component :is="entry.externalPage ? 'a' : 'router-link'"
        v-bind="entry.externalPage ? { href: entry.route, target: '_blank', rel: 'noopener' } : { to: entry.route }"
        class="signature-project-destination" :aria-label="`Explore ${showcase.title}`">
        <h3 :id="`${entry.id}-feature-title`"><span>{{ showcase.title }}</span><ArrowUpRightIcon class="signature-project-title-arrow" /></h3>
        <p>{{ showcase.description }}</p>
        <span class="signature-project-cta"><span>Explore the project</span></span>
      </component>
      <div class="signature-project-links">
        <GitHubRepoLink v-if="entry.id === 'slidepoise'" href="https://github.com/henryhyw/slidepoise" label="Source on GitHub" compact />
        <button v-else type="button" class="resource-action" @click="openView"><span>Compose a <AiViewTerm /></span></button>
        <ProjectArchitecture :project-id="entry.id" />
      </div>
      <div v-if="wide" class="signature-project-meta">
        <span class="signature-project-period">{{ entry.period }}</span>
        <SourceViewLinks :source-id="entry.sourceId" anchored @reveal-bottom="reserveViewSpace" />
      </div>
    </div>
    <ProjectShowcase :project-id="entry.id" />
    <div v-if="!wide" class="signature-project-meta signature-project-small-meta">
      <span class="signature-project-period">{{ entry.period }}</span>
      <SourceViewLinks :source-id="entry.sourceId" anchored @reveal-bottom="reserveViewSpace" />
    </div>
  </section>
</template>

<script>
import { projectShowcases } from '../../data/projectShowcases';
import ProjectShowcase from './ProjectShowcase.vue';
import ProjectArchitecture from './ProjectArchitecture.vue';
import GitHubRepoLink from './GitHubRepoLink.vue';
import SourceViewLinks from './SourceViewLinks.vue';
import AiViewTerm from './AiViewTerm.vue';
import '../../assets/css/resource-action.css';

export default {
  name: 'SignatureProject',
  components: { ProjectShowcase, ProjectArchitecture, GitHubRepoLink, SourceViewLinks, AiViewTerm },
  props: { entry: { type: Object, required: true } },
  data() { return { viewsOverflow: 0, wide: typeof window !== 'undefined' && window.innerWidth > 960 }; },
  mounted() {
    this._wideQuery = window.matchMedia('(min-width: 961px)');
    this._onWideChange = () => { this.wide = this._wideQuery.matches; this.viewsOverflow = 0; };
    this._wideQuery.addEventListener('change', this._onWideChange);
  },
  beforeUnmount() { this._wideQuery?.removeEventListener('change', this._onWideChange); },
  computed: { showcase() { return projectShowcases[this.entry.id]; } },
  methods: {
    openView() { window.dispatchEvent(new CustomEvent('open-site-view')); },
    reserveViewSpace(bottom) {
      if (bottom == null) { this.viewsOverflow = 0; return; }
      const section = this.$el;
      const contentBottom = section.getBoundingClientRect().bottom - parseFloat(getComputedStyle(section).paddingBottom);
      this.viewsOverflow = Math.max(0, Math.ceil(bottom - contentBottom + 12));
    }
  }
};
</script>

